import{_ as t,o as a,c as o,a2 as r}from"./chunks/framework.NwY0f7AV.js";const p=JSON.parse('{"title":"Changelog","description":"","frontmatter":{},"headers":[],"relativePath":"changelog.md","filePath":"changelog.md"}'),i={name:"changelog.md"};function n(s,e,l,c,d,h){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="changelog" tabindex="-1">Changelog <a class="header-anchor" href="#changelog" aria-label="Permalink to &quot;Changelog&quot;">​</a></h1><p>wraith follows <a href="https://semver.org" target="_blank" rel="noreferrer">semantic versioning</a>. While it&#39;s in beta (<code>0.x</code> pre-releases), any release may change the API; changes will be listed here.</p><h2 id="_0-1-0-beta-0" tabindex="-1">0.1.0-beta.0 <a class="header-anchor" href="#_0-1-0-beta-0" aria-label="Permalink to &quot;0.1.0-beta.0&quot;">​</a></h2><p>First public beta.</p><p><strong>Pages</strong></p><ul><li>Browser pages through Playwright (Chromium, Firefox, WebKit), and static pages without a browser, sharing one extraction API.</li><li><code>paginate()</code> in the browser (Next, Load more, infinite scroll) and without one; breadth-first <code>crawl()</code>.</li></ul><p><strong>Human behaviour</strong></p><ul><li>Curved mouse paths with Fitts&#39;s-law timing, overshoot and jitter; key-by-key typing with corrected typos; wheel scrolling; reading pauses.</li><li>Presets <code>off</code>, <code>fast</code>, <code>natural</code> and <code>careful</code>, every setting adjustable, and a <code>seed</code> for reproducible runs.</li></ul><p><strong>Extraction</strong></p><ul><li>Typed selector schemas with lists, nested fields, transforms and defaults.</li><li><code>near</code> and <code>text</code> matchers; role, label and text targets for sites with generated class names.</li><li><code>structuredData()</code> (JSON-LD, microdata, OpenGraph, meta tags, embedded JSON, app state) and <code>captureJson()</code>.</li></ul><p><strong>Waiting</strong></p><ul><li>Clickability checks before every click: visible, still, enabled and uncovered.</li><li><code>waitForSettled()</code>, <code>waitForText()</code>, <code>waitForUrl()</code>, <code>waitUntil()</code>, and <code>waits.afterAction</code>.</li></ul><p><strong>Interruptions</strong></p><ul><li>Consent banners answered with DuckDuckGo&#39;s autoconsent (<code>consent: &#39;reject&#39; | &#39;accept&#39;</code>).</li><li>CAPTCHA and one-time-code detection with a PNG of the challenge, and hand-off to a person.</li></ul><p><strong>AI</strong></p><ul><li><code>ai.extract()</code>, <code>ai.ask()</code> and <code>ai.act()</code> with Anthropic, OpenAI-compatible servers, Ollama, or your own provider; secrets passed as <code>%variables%</code>.</li></ul><p><strong>Network</strong></p><ul><li>Per-host rate limiting, retries with exponential backoff, optional robots.txt checks with Crawl-delay.</li></ul>',18)])])}const u=t(i,[["render",n]]);export{p as __pageData,u as default};
